import React, { Component } from 'react';
import Axios from 'axios';

import Header from './components/header';
import ListContainer from './components/MicList/listContainer';
import Pagination from './components/Pagination';

let that = null;
const entriesPerPage = 10;

export default class App extends Component {
  constructor(props) {
    super(props);

    this.state = {
      entries: [],
      width: window.innerWidth,
      height: window.innerHeight,
      sort: 'Date',
      sortType: 'Ascending',
      currentPage: 1,
      micFilter: 'approved'
    };

    that = this;
  }

  getEntries(status) {
    var auth = {
      method: 'GET',
      url: 'http://api.micmaps.com/api/mics',
      headers: {
        'Authorization' : window.sessionStorage.getItem('token')
      },
      params: {
        status: status
      }
    };

    return Axios(auth)
      .then((res) => {
        if(res.data.message === 'Mics!') {
          this.setState({ entries: res.data.data });
        }
        console.log(res);
      })
      .catch((err) => {
        this.props.history.push('/');
      })
  }

  updateDimensions() {
    let containerRightPadding = window.innerWidth*0.1041;
    let width = window.innerWidth - containerRightPadding/2;

    that.setState({width: width, height: window.innerHeight});
  }

  componentWillMount() {
    this.updateDimensions();
  }

  componentDidMount() {
    window.addEventListener("resize", this.updateDimensions);
  }

  componentWillUnmount() {
    window.removeEventListener("resize", this.updateDimensions);
  }

  toggleSort() {
    if(this.state.sortType === 'Ascending')
      this.setState({ sortType: 'Descending' });
    else
      this.setState({ sortType: 'Ascending' });
  }

  updatePage(pageNum) {
    this.setState({ currentPage: pageNum });
  }

  render() {
    if(window.sessionStorage.getItem('token') == null)
      this.props.history.push('/');

    if(this.state.entries.length == 0)
      this.getEntries(this.state.micFilter);

    let containerRightPadding = this.state.width*0.1041;
    let width = this.state.width - containerRightPadding/2;
    let leftOffset = (window.innerWidth - (.8125*window.innerWidth))/2;
    //left: `${50 - (175/window.innerWidth)*100}%`

    return (
      <div>
        <Header title='Admin Panel' />

        <div className='sortContainer' style={{display: 'flex', justifyContent: 'center', width: '100%'}}>
          <div style={{paddingRight: '5%'}}>
            <label>Sort by: </label>
            <select className='form-control sortForm' style={{marginLeft: '15px'}} onChange={(ev) => {this.setState({sort: ev.target.value})}}>
              <option className='dropdownItem'>Date</option>
              <option className='dropdownItem'>First Name</option>
              <option className='dropdownItem'>Last Name</option>
              <option className='dropdownItem'>City</option>
              <option className='dropdownItem'>Email</option>
            </select>

            <span className="fa fa-sort fa-2x clickable" aria-hidden="true" style={{position: 'absolute', marginLeft: '15px'}} onClick={() => this.toggleSort()}>
            </span>
          </div>

          <div style={{paddingLeft: '5%'}}>
            <label>Filter mics: </label>
            <select className='form-control sortForm' style={{marginLeft: '15px'}} onChange={(ev) => this.setState({entries: [], micFilter: ev.target.value.toLowerCase()})}>
              <option className='dropdownItem'>Approved</option>
              <option className='dropdownItem'>Pending</option>
              <option className='dropdownItem'>Rejected</option>
              <option className='dropdownItem'>Declined</option>
              <option className='dropdownItem'>All</option>
            </select>
          </div>
        </div>

        {this.state.entries.length > 0 ?
          <div>
            <div className='listContainer' style={{left: (leftOffset)+'px', width: width+'px'}}>
              <ListContainer entries={this.state.entries} sort={this.state.sort} sortType={this.state.sortType} entriesPerPage={entriesPerPage} currentPage={this.state.currentPage}/>
              <Pagination numEntries={this.state.entries.length} entriesPerPage={entriesPerPage} updatePage={(pageNum) => this.updatePage(pageNum)}/>
            </div>

            {/*<Pagination numEntries={this.state.entries.length} entriesPerPage={entriesPerPage} updatePage={(pageNum) => this.updatePage(pageNum)}/>*/}
          </div>
          : null }
      </div>
    );
  }
}



